const err = $input.first().error || {};
const msg = err.message || 'Unauthorized';
const isRate = msg.includes('RATE_LIMIT_EXCEEDED');

return [{
  json: {
    status:    isRate ? 'rate_limited' : 'unauthorized',
    message:   isRate
      ? 'Too many requests — limit is 100 per minute'
      : 'Invalid or missing authentication token',
    timestamp: new Date().toISOString()
  }
}];

const err = $input.first().error || {};
const message = err.message || 'Unknown validation error';
const isValidation = message.includes('VALIDATION_FAILED');

return [{
  json: {
    status:    isValidation ? 'rejected' : 'error',
    message:   message.replace('VALIDATION_FAILED: ', ''),
    timestamp: new Date().toISOString()
  }
}];
